/* ---------- A-22 ---------- */
function A22() {
  const rows = WITHDRAWALS.filter(w => ['under_review', 'approved', 'submitted'].includes(w.status)).map(w => {
    const m = member(w.memberId);
    const withinLimit = w.amount <= 5000000;
    return `<tr onclick="go('#a23')">
      <td><button class="chk" onclick="event.stopPropagation()">${ic('check')}</button></td>
      <td><b style="font-variant-numeric:tabular-nums">${w.no}</b><div class="fs-xs mut">${w.submitted} · ${w.at}</div></td>
      <td><div class="who"><div class="avatar sm">${m.photo}</div><div><b>${m.name}</b><i>${m.no}</i></div></div></td>
      <td class="num" style="font-size:15.5px">${tk(w.amount)}</td>
      <td>${w.reason}<div class="fs-xs mut">${channel[w.method] ? channel[w.method].t : (w.method === 'cash_office' ? 'অফিস কাউন্টার (নগদ)' : w.method)}</div></td>
      <td><span class="chip ${w.status === 'approved' ? 'chip-ok' : 'chip-warn'}">${ic(w.status === 'approved' ? 'checkc' : 'clock')}${w.step}</span></td>
      <td>${withinLimit ? `<span class="chip chip-ok">${ic('check')}সীমার মধ্যে</span>` : `<span class="chip chip-purple">${ic('shield')}APPROVER দরকার</span>`}</td>
      <td class="num">${w.noticeEnds ? dshort(w.noticeEnds) : '—'}</td>
      <td><div class="btn-row" style="gap:6px">
        ${w.status === 'approved' ? `<button class="btn btn-primary btn-sm" onclick="event.stopPropagation();go('#a24')">${ic('cash','sm')} নিষ্পত্তি</button>`
        : `<button class="btn btn-soft btn-sm" onclick="event.stopPropagation();go('#a23')">${ic('check','sm')} অনুমোদন</button>
           <button class="btn btn-danger btn-sm" onclick="event.stopPropagation()">${ic('x','sm')}</button>`}</div></td></tr>`;
  }).join('');
  return admScreen('a22', 'A-22', 'উত্তোলন অনুমোদন কিউ', 'MANAGER (A) · APPROVER (A) · ACCOUNTANT (R) · AUDITOR (R)',
    'উত্তোলনের আবেদন <b>যোগ্যতা</b> ও <b>সমিতির নগদ সক্ষমতা</b> দেখে নিষ্পত্তি করা। অনুমোদনের সীমা (D-22) অতিক্রম হলে উচ্চতর ধাপে রাউট হয়।',
    [must, T('', 'নগদ সক্ষমতা দেখানো'), T('', 'অনুমোদন সীমা রাউটিং'), T('def', 'ডিফল্ট · D-02 নোটিশ ৭ দিন'), T('def', 'ডিফল্ট · D-22 সীমা')],
    'wdappr',
    `${adminTop('উত্তোলন অনুমোদন', `লেনদেন › উত্তোলন › কিউ`, `
      <button class="btn btn-ghost btn-sm">${ic('download','sm')} এক্সপোর্ট</button>
      <button class="btn btn-primary btn-sm">${ic('check','sm')} নির্বাচিত ১টি অনুমোদন</button>`)}
    <div class="admin-content">
      <div class="alert alert-warn mb-16">${ic('cash')}
        <div><b>হাতে নগদ কম — ${tk(186400)}</b> আজ ২টি অফিস-কাউন্টার নিষ্পত্তি বাকি (মোট ${tk(2200000)})।
          অনুমোদন আটকাবে না (D-02 ডিফল্ট), কিন্তু নিষ্পত্তি বিলম্বিত হতে পারে — ব্যাংক থেকে নগদ আনার অনুরোধ পাঠানো হয়েছে।</div>
        <button class="btn btn-ghost btn-sm act">নগদ পরিকল্পনা</button></div>

      <div class="kpis mb-16">
        <div class="kpi"><div class="kpi-l">অপেক্ষমাণ আবেদন</div><div class="kpi-v">${bn(6)}টি</div><div class="kpi-a">মোট ${tk(3650000)}</div></div>
        <div class="kpi"><div class="kpi-l">আপনার সীমার মধ্যে</div><div class="kpi-v">${bn(4)}টি</div><div class="kpi-a">সীমা ${tk(5000000)} (D-22)</div></div>
        <div class="kpi"><div class="kpi-l">নিষ্পত্তির অপেক্ষায়</div><div class="kpi-v">${bn(2)}টি</div><div class="kpi-a">${tk(2700000)} · A-24-এ যান</div></div>
        <div class="kpi"><div class="kpi-l">গড় নিষ্পত্তি সময়</div><div class="kpi-v">${bn(2)} দিন</div><div class="kpi-a">নোটিশ পিরিয়ড ৭ দিনসহ</div></div>
      </div>

      <div class="tbl-wrap">
        <div class="tbl-tools">
          <button class="chip-btn on">চলমান (${bn(4)})</button><button class="chip-btn">অনুমোদিত · নিষ্পত্তি বাকি (${bn(2)})</button>
          <button class="chip-btn">সম্পন্ন</button><button class="chip-btn">প্রত্যাখ্যাত</button>
          <button class="chip-btn">${ic('filter','sm')} স্কিম</button><button class="chip-btn">${ic('cash','sm')} মাধ্যম</button>
          <button class="chip-btn" style="margin-left:auto">${ic('sort','sm')} অপেক্ষার সময়</button>
        </div>
        <div class="tbl-scroll"><table class="tbl"><thead><tr>
          <th style="width:34px"><button class="chk">${ic('check')}</button></th>
          <th>আবেদন নং</th><th>সদস্য</th><th class="num">পরিমাণ</th><th>কারণ / মাধ্যম</th>
          <th>বর্তমান ধাপ</th><th>অনুমোদন সীমা</th><th class="num">নোটিশ শেষ</th><th>অ্যাকশন</th></tr></thead>
          <tbody>${rows}</tbody></table></div>
        <div class="tbl-sum">
          <div><i>নির্বাচিত</i><b>${tk(500000)}</b></div>
          <div><i>চলমান মোট</i><b>${tk(3650000)}</b></div>
          <div><i>নিষ্পত্তির পর হাতে নগদ থাকবে</i><b style="color:var(--danger-ink)">${tk(0)} (ঘাটতি)</b></div>
        </div>
      </div>
    </div>`,
    `<span class="lbl">Insufficient cash</span><span class="val">হলুদ ব্যানার, অনুমোদন আটকায় না · </span>
     <span class="lbl">Limit exceeded</span><span class="val">বাটন নিষ্ক্রিয় + "APPROVER দরকার" · </span>
     <span class="lbl">Queue empty</span><span class="val">ইতিবাচক স্টেট</span>`);
}

