/* ---------- S-02 · সমিতি নির্বাচন (Organization Switcher) ---------- */
function S02() {
  const orgCard = (o, role, saving, on, last) => `<div class="radio-card ${on ? 'on' : ''}" style="display:block;padding:0;border-radius:18px;overflow:hidden">
      <div style="padding:14px 15px;display:flex;gap:12px;align-items:flex-start">
        <span class="dotr" style="margin-top:3px"></span>
        <div class="grow" style="min-width:0">
          <div class="hrow" style="gap:8px;flex-wrap:wrap"><b style="font-size:16px">${o.name}</b>
            ${on ? '<span class="chip chip-ok">বর্তমান</span>' : ''}</div>
          <div class="fs-xs mut mt-4">নিবন্ধন ${o.reg} · ${o.area}</div>
          <div class="fs-xs mt-8"><span class="chip chip-info">${ic('shield','sm')} আপনার ভূমিকা: ${role}</span></div>
          <div class="grid2 mt-12">
            <div><div class="fs-xs mut">মোট সঞ্চয়</div><b class="fs-md sb">${tk(saving)}</b></div>
            <div class="t-r"><div class="fs-xs mut">সর্বশেষ ব্যবহার</div><b class="fs-sm sb">${last}</b></div>
          </div>
        </div></div>
      <div class="card-f" style="padding:9px 15px"><button class="link">এই সমিতিতে প্রবেশ ${ic('chev','sm')}</button></div>
    </div>`;
  return `${statusBar()}
  ${mhead({ back: '#m18', title: 'আমার সমিতিসমূহ', sub: '২টি সমিতিতে আপনার সদস্যপদ আছে', plain: true,
    right: `<button class="iconbtn plain">${ic('logout')}</button>` })}
  <div class="phone-scroll"><div class="appbody">
    <div class="alert alert-info mb-16">${ic('info')}
      <div><b>কোন সমিতির হিসাব দেখছেন তা সবসময় উপরে লেখা থাকবে</b> একাধিক সমিতির সদস্য হলে দুটি ব্যালেন্স মিশে যাওয়ার ঝুঁকি থাকে — তাই প্রতিটি স্ক্রিনের হেডারে সমিতির নাম দেখানো হয়।</div></div>

    <div class="stack-16">
      ${orgCard(ORG, 'MEMBER', member(ME).total, true, 'আজ')}
      ${orgCard(ORG2, 'MEMBER', 2140000, false, '১২ অক্টো')}
    </div>

    <div class="card pad mt-20">
      <b class="fs-md sb">নতুন সমিতিতে যোগ দিন</b>
      <div class="fs-xs mut mt-4" style="line-height:1.6">সমিতির দেওয়া <b>ইনভাইট কোড</b> থাকলে এখানে দিন — আবেদন যাচাইয়ের অপেক্ষায় যাবে (D-18)। কোড না থাকলে সমিতির অফিসে যোগাযোগ করুন।</div>
      <div class="field mt-12 mb-0"><label>ইনভাইট কোড</label>
        <input class="inp" placeholder="যেমন: ${ORG.invite}" style="letter-spacing:1.5px;font-weight:600">
        <div class="hlp">কোডটি সমিতির নোটিশ বোর্ডে বা SMS-এ পাওয়া যাবে।</div></div>
      <button class="btn btn-soft btn-block btn-sm mt-12">${ic('send','sm')} যোগদানের অনুরোধ পাঠান</button>
    </div>

    <div class="card pad mt-16" style="background:var(--green-050);border-color:var(--ok-bd)">
      <div class="hrow" style="gap:11px"><span class="txi lime">${ic('info')}</span>
        <div class="grow"><b class="fs-md sb">একটি সমিতি থাকলে এই পেজ আসবে না</b>
          <div class="fs-xs mut mt-4" style="line-height:1.6">শুধু এক সমিতির সদস্য হলে লগইনের পর সরাসরি হোমে চলে যাবেন — অপ্রয়োজনীয় ধাপ এড়ানো হবে।</div></div></div>
    </div>

    <button class="btn btn-ghost btn-block mt-20">${ic('logout','sm')} লগআউট</button>
    <div class="t-c mt-16">${staleNote()}</div>
  </div></div>${bottomNav('more')}`;
}

