/* ---------- M-15 · অ্যাকাউন্ট বন্ধের আবেদন ও নিষ্পত্তি প্রিভিউ ---------- */
function M15() {
  const a = acc('a8'), m = member(a.memberId), s = scheme(a.schemeId);
  const CP = CLOSURE_PREVIEW;
  const wdOpen = WITHDRAWALS.filter(w => ['submitted', 'under_review', 'approved', 'disbursing'].indexOf(w.status) >= 0 && w.accId === 'a8').length;
  const row = (label, amt, tone) => `<div class="hrow" style="padding:9px 0;border-bottom:1px dashed var(--line)">
      <div class="grow"><div class="fs-sm b">${label}</div></div>
      <div class="amt ${amt < 0 ? 'amt-neg' : amt > 0 ? 'amt-pos' : 'amt-mut'} amt-sm">${amt === 0 ? '৳০' : (amt < 0 ? '− ' : '') + tk(Math.abs(amt))}</div></div>`;
  return `${statusBar()}
  ${mhead({ back: '#m05', title: 'অ্যাকাউন্ট বন্ধ', sub: a.no, plain: true })}
  <div class="phone-scroll"><div class="appbody">

    ${wdOpen ? `<div class="alert alert-danger">${ic('warn')}<div><b>আগে এগুলো নিষ্পত্তি হোক</b>${bn(wdOpen)}টি চলমান উত্তোলন আবেদন আছে। সেগুলো নিষ্পত্তি বা বাতিল না হলে বন্ধের আবেদন নেওয়া যাবে না। <a class="link" onclick="go('#m12')">আবেদন দেখুন →</a></div></div>` : ''}

    <div class="card pad">
      <div class="hrow"><div class="txi hold">${ic('logout')}</div>
        <div class="grow"><b class="fs-md sb">${s.name} বন্ধ করবেন?</b>
        <div class="fs-xs mut">${m.name} · ${bn(a.paidInstallments)}টি কিস্তি জমা · খোলা ${dstr(a.opened)}</div></div>
        ${CHIP(ACC_STATUS, a.status)}</div>
      <div class="alert alert-warn mt-12" style="padding:10px 12px;font-size:12.8px">${ic('info','sm')}
        <div><b>বন্ধ হলে কী হবে</b>সময়সূচি বাতিল · নতুন জমা বন্ধ · রেকর্ড ৮ বছর সংরক্ষিত থাকবে (মুছে যাবে না) · সদস্যপদ আলাদা বিষয় ${defChip('D-19')}</div></div>
    </div>

    ${secH('আপনি ঠিক কত পাবেন — ধাপে ধাপে', 'সব কর্তনের কারণসহ')}
    <div class="card pad">
      ${CP.steps.map(x => row(x[0], x[1], x[2])).join('')}
      <div class="hrow mt-12" style="padding:11px 12px;border-radius:14px;background:var(--neutral-bg)">
        <div class="grow"><div class="fs-sm mut">নিট হিসাব</div></div>
        <div class="amt amt-h2 ${CP.net < 0 ? 'amt-neg' : ''}">${CP.net < 0 ? '− ' : ''}${tk(Math.abs(CP.net))}</div></div>
      <div class="hrow mt-8" style="padding:13px 14px;border-radius:14px;background:var(--green-050);border:1px solid var(--ok-bd)">
        <div class="grow"><div class="fs-sm b" style="color:var(--green-800)">চূড়ান্ত প্রদেয়</div>
        <div class="fs-xs mut">সমিতির পাওনা বেশি হলে প্রদেয় ৳০ — ঋণ হিসেবে দাবি করা হয় না ${defChip('D-19')}</div></div>
        <div class="amt amt-h1">${tk(CP.payable)}</div></div>
    </div>

    <div class="alert alert-danger mt-16">${ic('warn')}<div><b>প্রদেয় শূন্য — কেন?</b>
      আপনার মোট জমা ${tk(CP.steps[0][1])}, কিন্তু বকেয়া ৬টি কিস্তি ${tk(Math.abs(CP.steps[1][1]))} ও ফি ${tk(Math.abs(CP.steps[2][1] + CP.steps[3][1]))} — মোট কর্তন বেশি।
      সমিতির পাওনা ${tk(Math.abs(CP.net))} মওকুফ করতে <b>কমিটির লিখিত সিদ্ধান্ত</b> লাগবে ${defChip('D-09')}।
      <a class="link" onclick="go('#m18')">অফিসে যোগাযোগ করুন →</a></div></div>

    ${secH('আবেদন')}
    <div class="card pad">
      <div class="field"><label>কেন বন্ধ করতে চান?</label>
        <div class="chipset mt-8">
          <span class="chip chip-btn on">এলাকা ছেড়ে চলে যাচ্ছি</span><span class="chip chip-btn">টাকার প্রয়োজন</span>
          <span class="chip chip-btn">স্কিম বদলাতে চাই</span><span class="chip chip-btn">অন্য কারণ</span></div></div>
      <div class="field mt-12"><label>টাকা কোন মাধ্যমে পাবেন?</label>
        <div class="chipset mt-8"><span class="chip chip-btn on">${ic('phone','sm')} বিকাশ (01711-456789)</span>
          <span class="chip chip-btn">${ic('cash','sm')} অফিস কাউন্টার</span></div></div>
      <div class="kv mt-12"><i>নোটিশ পিরিয়ড</i><b>${bn(CP.noticeDays)} দিন ${defChip('D-02')}</b></div>
      <div class="kv"><i>প্রত্যাশিত নিষ্পত্তি</i><b>${dstr(daysAhead(CP.noticeDays), true)}</b></div>
      <div class="kv"><i>সম্মতি</i><b>সংস্করণ ৩ · ${dstr('2026-07-01')} ${defChip('D-23')}</b></div>
      <div class="note mt-8">নোটিশ পিরিয়ডেও জমা দিতে পারবেন; নতুন উত্তোলন আবেদন আটকাবে।</div>
    </div>

    ${secH('আগের আবেদন', 'এই অ্যাকাউন্টে')}
    <div class="card pad">
      <div class="hrow"><span class="chip chip-warn">${ic('clock')} ClosureRequested</span>
        <div class="grow"><div class="fs-sm b">CL-2627-০৩৪</div><div class="fs-xs mut">২৭ অক্টোবর · অনুমোদনের অপেক্ষায়</div></div></div>
      <div class="tl mt-12">
        <div class="tl-i done"><b>আবেদন জমা</b><i>২৭ অক্টোবর, সকাল ১০:১৫ · OTP যাচাইকৃত</i></div>
        <div class="tl-i cur"><b>ক্লিয়ারেন্স পর্যালোচনা</b><i>হিসাবরক্ষক বকেয়া ও ফি মিলিয়ে দেখছেন · A-15</i></div>
        <div class="tl-i"><b>অনুমোদন (MANAGER/APPROVER)</b><i>maker ≠ checker যাচাই হবে</i></div>
        <div class="tl-i"><b>নিষ্পত্তি ও সনদ</b><i>প্রত্যাশিত ${dstr(daysAhead(CP.noticeDays))}</i></div>
      </div>
      <div class="btn-row mt-12"><button class="btn btn-ghost btn-sm grow">${ic('xc','sm')} আবেদন প্রত্যাহার</button>
        <button class="btn btn-soft btn-sm grow" onclick="go('#m14')">${ic('doc','sm')} ক্লিয়ারেন্স সনদ</button></div>
    </div>

    <div class="alert alert-neutral mt-16">${ic('info')}<div><b>বিকল্প আছে</b>
      পুরো টাকা তুলতে চাইলে বন্ধ না করে <a class="link" onclick="go('#m10')">উত্তোলনের আবেদন</a> করতে পারেন — সদস্যপদ ও সময়সূচি ঠিক থাকবে।
      স্কিম বদলাতে চাইলে অফিসে বলুন।</div></div>

    <div class="t-c mt-16 mb-16">${staleNote()}</div>
  </div></div>
  <div class="stickyfoot" style="margin-bottom:0">
    <div class="sum"><i>চূড়ান্ত প্রদেয়</i><b>${tk(CP.payable)}</b></div>
    <button class="btn btn-ghost" onclick="go('#m05')">বাতিল</button>
    <button class="btn btn-danger-solid" onclick="go('#s02')">${ic('lock','sm')} OTP দিয়ে জমা দিন</button>
  </div>`;
}

/* ---------- M-17 · নোটিশ বোর্ড ---------- */
function M17() {
  const live = NOTICES.filter(n => !n.expired), old = NOTICES.filter(n => n.expired);
  const card = (n, archived) => {
    const k = NOTICE_KIND[n.kind];
    return `<div class="card pad ${archived ? 'stale' : ''}">
      <div class="hrow" style="align-items:flex-start">
        <span class="txi ${n.urgent ? 'danger' : n.kind === 'meeting' ? 'info' : 'lime'}" style="width:34px;height:34px;border-radius:11px">${ic(k.i,'sm')}</span>
        <div class="grow" style="min-width:0"><b class="fs-md sb">${n.title}</b>
          <div class="fs-xs mut mt-4">${dstr(n.published)} · ${n.by}</div></div>
        <span class="chip ${k.c}">${k.t}</span></div>
      <p class="mt-8" style="font-size:13.6px;line-height:1.66;color:var(--txt-2)">${n.body}</p>
      ${archived ? `<div class="chip chip-neutral mt-8">${ic('clock','sm')} মেয়াদোত্তীর্ণ (${dshort(n.validTill)})</div>` :
        n.urgent ? `<div class="chip chip-danger mt-8">${ic('warn','sm')} মেয়াদ ${dshort(n.validTill)} পর্যন্ত</div>` : ''}
      ${n.attach ? `<div class="hrow mt-12" style="padding:9px 11px;border:1px dashed var(--line-3);border-radius:13px;background:var(--card-2)">
        ${ic('doc','sm')}<div class="grow" style="min-width:0"><div class="fs-xs b">${n.attach}</div><div class="fs-xs mut">${n.size}</div></div>
        <button class="btn btn-soft btn-sm">${ic('download','sm')}</button></div>` : ''}
      <div class="btn-row mt-12">
        <button class="btn btn-ghost btn-sm grow">${archived ? 'আর্কাইভ থেকে দেখুন' : 'বিস্তারিত পড়ুন'}</button>
        <button class="btn btn-ghost btn-sm" onclick="go('#s07')">${ic('share','sm')}</button></div></div>`;
  };
  return `${statusBar()}
  ${mhead({ back: '#m01', title: 'নোটিশ বোর্ড', sub: `${bn(live.length)}টি চলতি · ${bn(old.length)}টি আর্কাইভ`, plain: true,
    right: `<button class="iconbtn plain">${ic('search')}</button>` })}
  <div class="phone-scroll"><div class="appbody">

    <div class="alert alert-info">${ic('info')}<div><b>মাইকিংয়ের ডিজিটাল বিকল্প</b>
      সমিতির প্রতিটি ঘোষণা এখানে থাকে — সভা, ছুটি, নতুন স্কিম ও জরুরি নোটিশ। SMS-এ লিংক পাবেন।</div></div>

    ${NOTICES.filter(n => n.pinned && !n.expired).map(n => `<div class="mt-16">${card(n)}</div>`).join('')}

    ${secH('সব ঘোষণা', `${bn(live.length)}টি`)}
    <div class="chipset"><span class="chip chip-btn on">সব</span><span class="chip chip-btn">সভা</span>
      <span class="chip chip-btn">জরুরি</span><span class="chip chip-btn">স্কিম</span><span class="chip chip-btn">পড়া হয়নি</span></div>
    <div class="stack-12 mt-12">${live.filter(n => !n.pinned).map(n => card(n)).join('')}</div>

    ${secH('আর্কাইভ', 'মেয়াদোত্তীর্ণ')}
    <div class="stack-12">${old.map(n => card(n, true)).join('')}</div>

    <div class="card pad mt-16 t-c">
      <div class="state state-sm" style="padding:6px">${ic('doc')}
        <h4>পুরনো নোটিশ খুঁজছেন?</h4>
        <p>৮ বছরের সব ঘোষণা সংরক্ষিত থাকে — বছর বেছে দেখুন।</p></div>
      <div class="btn-row mt-8" style="justify-content:center"><span class="chip chip-btn">২০২৬</span><span class="chip chip-btn">২০২৫</span><span class="chip chip-btn">২০২৪</span></div>
    </div>

    <div class="t-c mt-16 mb-16">${staleNote()}</div>
  </div></div>
  ${bottomNav('home')}`;
}

/* ---------- M-19 · নমিনি ব্যবস্থাপনা ---------- */
function M19() {
  const mine = NOMINEES.filter(n => n.memberId === ME);
  const total = mine.filter(n => n.status === 'active').reduce((s, n) => s + n.share, 0);
  const ch = NOMINEE_CHANGE;
  const docChip = { ok: 'chip-ok', blur: 'chip-warn', pending: 'chip-warn', missing: 'chip-danger', na: 'chip-neutral' };
  const docTxt = { ok: 'যাচাইকৃত', blur: 'অস্পষ্ট ছবি', pending: 'সম্মতি বাকি', missing: 'জমা দেওয়া হয়নি', na: 'প্রযোজ্য নয়' };
  return `${statusBar()}
  ${mhead({ back: '#m18', title: 'নমিনি', sub: `${bn(mine.length)} জন · মোট অংশ ${bn(total)}%`, plain: true,
    right: `<button class="iconbtn plain">${ic('more')}</button>` })}
  <div class="phone-scroll"><div class="appbody">

    ${total === 100 ? `<div class="alert alert-ok">${ic('checkc')}<div><b>অংশ বণ্টন ঠিক আছে</b>মোট ১০০% — কোনো সমস্যা নেই। সর্বশেষ পরিবর্তন অনুমোদিত হয়েছে ${dstr('2024-03-12')}।</div></div>`
      : `<div class="alert alert-danger">${ic('warn')}<div><b>মোট ${bn(total)}% — ১০০% হতে হবে</b>অংশ বণ্টন সম্পূর্ণ না হলে নতুন নমিনি জমা নেওয়া হবে না।</div></div>`}

    <div class="alert alert-warn mt-12">${ic('info')}<div><b>কেন এটি জরুরি</b>
      নমিনি ঠিক করা থাকলে মৃত্যু বা অক্ষমতার ক্ষেত্রে টাকা দ্রুত ও ঝগড়া ছাড়া হস্তান্তর হয়। গ্রামীণ সমবায়ে এটিই সবচেয়ে বেশি বিরোধের কারণ — তাই ডিজিটাল রেকর্ড রাখা আপনার সুরক্ষা।</div></div>

    ${secH('মনোনীত নমিনি', 'সক্রিয়')}
    <div class="stack-12">${mine.map(n => `<div class="card pad">
      <div class="hrow"><div class="avatar">${n.photo}</div>
        <div class="grow" style="min-width:0"><b class="fs-md sb">${n.name}</b>
        <div class="fs-xs mut">${n.rel} · NID ${n.nid}</div></div>
        <div class="t-c"><div class="amt amt-h2">${bn(n.share)}%</div><div class="fs-xs mut">অংশ</div></div></div>
      <div class="prog mt-12"><i style="width:${n.share}%"></i></div>
      <div class="hrow mt-8" style="gap:6px;flex-wrap:wrap">
        <span class="chip ${n.status === 'active' ? 'chip-ok' : 'chip-warn'}">${n.status === 'active' ? ic('checkc','sm') + 'সক্রিয়' : ic('clock','sm') + 'অনুমোদনের অপেক্ষায়'}</span>
        ${Object.keys(n.docs).map(k => `<span class="chip ${docChip[n.docs[k]]}">${({nid:'NID',photo:'ছবি',consent:'সম্মতি'})[k]} · ${docTxt[n.docs[k]]}</span>`).join('')}</div>
      <div class="kv mt-12"><i>প্রযোজ্য অ্যাকাউন্ট</i><b>${n.accIds.map(id => acc(id).no).join(', ')}</b></div>
      <div class="kv"><i>যোগ করা</i><b>${dstr(n.addedAt)} · অনুমোদন ${n.approvedBy}</b></div>
      <div class="btn-row mt-12"><button class="btn btn-ghost btn-sm grow">${ic('edit','sm')} সম্পাদনা</button>
        <button class="btn btn-ghost btn-sm grow">${ic('doc','sm')} ডকুমেন্ট</button>
        <button class="btn btn-ghost btn-sm">${ic('trash','sm')}</button></div>
    </div>`).join('')}</div>

    ${secH('পরিবর্তনের অনুরোধ', 'অনুমোদনের অপেক্ষায়')}
    <div class="card pad">
      <div class="hrow"><span class="chip chip-warn">${ic('clock')} PendingApproval</span>
        <div class="grow"><div class="fs-sm b">${dstr(ch.at)} · ${ch.by}</div>
        <div class="fs-xs mut">অনুমোদনকারী: ${ch.approver}</div></div></div>
      <div class="alert alert-info mt-12" style="padding:10px 12px;font-size:12.8px">${ic('shield','sm')}
        <div><b>অনুমোদন না হওয়া পর্যন্ত পুরনো নমিনিই সক্রিয় থাকবে</b>কোনো ফাঁক নেই — দাবির সময় যাচাইকৃত তালিকাই ব্যবহার হবে।</div></div>
      <table class="tbl" style="margin-top:12px">
        <thead><tr><th>নমিনি</th><th class="num">আগে</th><th class="num">প্রস্তাব</th></tr></thead>
        <tbody>
          ${ch.to.map((t, k) => `<tr><td>${t.name}${t.rel ? `<div class="fs-xs mut">${t.rel}</div>` : ''}</td>
            <td class="num">${ch.from[k] ? bn(ch.from[k].share) + '%' : '—'}</td><td class="num b">${bn(t.share)}%</td></tr>`).join('')}
          <tr><td class="b">মোট</td><td class="num">${bn(ch.from.reduce((s, x) => s + x.share, 0))}%</td>
            <td class="num b">${bn(ch.to.reduce((s, x) => s + x.share, 0))}%</td></tr></tbody></table>
      <div class="note mt-8">কারণ: ${ch.reason}</div>
      <div class="btn-row mt-12"><button class="btn btn-ghost btn-sm grow">${ic('xc','sm')} অনুরোধ প্রত্যাহার</button>
        <button class="btn btn-soft btn-sm grow">${ic('clock','sm')} অবস্থা দেখুন</button></div>
    </div>

    ${secH('নমিনি যোগ করতে যা লাগবে')}
    <div class="card pad">
      <div class="rows">
        <div class="row"><span class="txi ok">${ic('doc')}</span><div class="row-tx"><b>নমিনির NID</b><i>সামনে ও পেছনের ছবি</i></div><span class="chip chip-neutral">বাধ্যতামূলক</span></div>
        <div class="row"><span class="txi ok">${ic('cam')}</span><div class="row-tx"><b>নমিনির ছবি</b><i>স্পষ্ট, মুখ দেখা যায় এমন</i></div><span class="chip chip-neutral">বাধ্যতামূলক</span></div>
        <div class="row"><span class="txi ok">${ic('edit')}</span><div class="row-tx"><b>নমিনির সম্মতি/স্বাক্ষর</b><i>সম্মতি ছাড়া মনোনয়ন সম্পূর্ণ নয়</i></div><span class="chip chip-warn">সম্মতি বাকি</span></div>
        <div class="row"><span class="txi ok">${ic('scale')}</span><div class="row-tx"><b>অংশ বণ্টন</b><i>সব নমিনির মোট = ১০০%</i></div><span class="chip chip-ok">ঠিক আছে</span></div>
      </div>
    </div>

    <div class="alert alert-neutral mt-16">${ic('shield')}<div><b>স্টাফ পরিবর্তন করলে</b>
      নমিনি পরিবর্তনের অধিকার কেবল আপনার। অফিস থেকে কোনো পরিবর্তন করা হলে অডিট লগে থাকবে এবং আপনাকে SMS যাবে।</div></div>

    <div class="t-c mt-16 mb-16">${staleNote()}</div>
  </div></div>
  <div class="stickyfoot" style="margin-bottom:0">
    <div class="sum"><i>মোট অংশ</i><b>${bn(total)}%</b></div>
    <button class="btn btn-primary btn-block" onclick="go('#m08')">${ic('plus','sm')} নতুন নমিনি যোগ করুন</button>
  </div>`;
}

/* ---------- M-20 · অ্যাকাউন্ট ও নিরাপত্তা সেটিংস ---------- */
function M20() {
  const me = member(ME), P = PREFS;
  const row = (ico, title, sub, right) => `<div class="row" style="padding:12px 0;border-bottom:1px solid var(--line)">
      <span class="txi ${right && right.indexOf('বন্ধ') >= 0 ? 'mut' : 'ok'}">${ic(ico)}</span>
      <div class="row-tx"><b>${title}</b><i>${sub}</i></div>${right || ''}</div>`;
  const tg = (on, label) => `<span class="chip ${on ? 'chip-ok' : 'chip-neutral'}">${on ? ic('checkc','sm') + label : ic('xc','sm') + label}</span>`;
  return `${statusBar()}
  ${mhead({ back: '#m18', title: 'নিরাপত্তা ও পছন্দ', sub: me.no, plain: true })}
  <div class="phone-scroll"><div class="appbody">

    ${DEVICES.filter(d => d.suspect).map(d => `<div class="alert alert-danger">${ic('warn')}<div><b>অচেনা ডিভাইস থেকে লগইন</b>
      ${d.name} · ${d.place} · ${d.last}। আপনি না হলে এখনই লগআউট করুন ও পিন বদলান।
      <a class="link">ডিভাইস সরান →</a></div></div>`).join('')}

    ${secH('লগইন ও নিরাপত্তা')}
    <div class="card pad">
      ${row('lock', 'পিন (PIN)', '৬ সংখ্যা · সর্বশেষ বদল ৪ মাস আগে', `<button class="btn btn-ghost btn-sm">বদলান</button>`)}
      ${row('user', 'বায়োমেট্রিক (আঙুলের ছাপ)', 'এই ডিভাইসে সমর্থিত, কিন্তু বন্ধ আছে', tg(P.bio, 'বন্ধ'))}
      ${row('clock', 'সেশন টাইমআউট', `${bn(P.timeout)} মিনিট নিষ্ক্রিয় থাকলে লগআউট`, `<span class="chip chip-neutral">${bn(P.timeout)} মিনিট</span>`)}
      ${row('shield', 'লেনদেন সীমা (দৈনিক)', 'এর বেশি হলে অতিরিক্ত OTP লাগবে', `<span class="chip chip-neutral">${tk(P.txnLimit)}</span>`)}
      ${row('phone', 'মোবাইল নম্বর', `${me.mobile} · বদলাতে পুরনো + নতুন দুটোতেই OTP ${''}`, `<span class="chip chip-warn">${ic('lock','sm')}দ্বৈত OTP</span>`)}
      <div class="note mt-8">${defChip('D-21')} নম্বর বদলে পুরনো নম্বরেও OTP যাবে — যাতে কেউ আপনার নম্বর বদলে দিতে না পারে।</div>
    </div>

    <div class="alert alert-warn mt-12">${ic('warn')}<div><b>পিন দুর্বল হলে ঝুঁকি</b>
      ১২৩৪৫৬, জন্মতারিখ বা একই অঙ্ক ৬ বার — এমন পিন দিলে সহজেই অনুমান করা যায়। ৩ বার ভুল পিন দিলে অ্যাকাউন্ট ১৫ মিনিট লক হবে।</div></div>

    ${secH('সক্রিয় ডিভাইস', `${bn(DEVICES.length)}টি`)}
    <div class="card pad">
      ${DEVICES.map(d => `<div class="hrow" style="padding:11px 0;border-bottom:1px dashed var(--line)">
        <span class="txi ${d.current ? 'ok' : d.suspect ? 'danger' : 'mut'}">${ic(d.current ? 'checkc' : d.suspect ? 'warn' : 'phone')}</span>
        <div class="grow" style="min-width:0"><div class="fs-sm b">${d.name}</div>
          <div class="fs-xs mut">${d.place} · শেষ ব্যবহার ${d.last}${d.ip !== '—' ? ' · IP ' + d.ip : ''}</div></div>
        ${d.current ? '<span class="chip chip-ok">এই ডিভাইস</span>' : `<button class="btn btn-ghost btn-sm ${d.suspect ? 'btn-danger' : ''}">${d.suspect ? 'এখনই সরান' : 'লগআউট'}</button>`}</div>`).join('')}
      <button class="btn btn-danger btn-block btn-sm mt-12">${ic('logout','sm')} সব ডিভাইস থেকে লগআউট</button>
    </div>

    ${secH('নোটিফিকেশন পছন্দ')}
    <div class="card pad">
      ${[['txn', 'লেনদেন (জমা/উত্তোলন)', 'প্রতিটি লেনদেনের সাথে সাথে — এটি বন্ধ করা যাবে না', true],
         ['dues', 'বকেয়া রিমাইন্ডার', 'কিস্তির ৩ দিন আগে ও পরে', P.notif.dues],
         ['scheme', 'স্কিম ও মেয়াদ', 'মেয়াদ পূর্ণ, নিয়ম পরিবর্তন', P.notif.scheme],
         ['notice', 'নোটিশ বোর্ড', 'সমিতির ঘোষণা', P.notif.notice]].map(x =>
        row('bell', x[1], x[2], x[3] ? tg(true, 'চালু') : tg(x[3], 'চালু'))).join('')}
      <div class="hrow" style="padding:12px 0"><span class="txi ok">${ic('send')}</span>
        <div class="row-tx"><b>চ্যানেল</b><i>SMS ও পুশ — দুটোই চালু</i></div>
        <span class="chip chip-ok">SMS + Push</span></div>
      <div class="note mt-8">SMS বন্ধ করলে গ্রামীণ এলাকায় গুরুত্বপূর্ণ বার্তা মিস হতে পারে — SMS চালু রাখার পরামর্শ।</div>
    </div>

    ${secH('ভাষা ও সংখ্যা')}
    <div class="card pad">
      <div class="field"><label>ভাষা (তাৎক্ষণিক পরিবর্তন)</label>
        <div class="seg mt-8"><button class="on">বাংলা</button><button>English</button></div></div>
      <div class="field mt-12"><label>সংখ্যা পদ্ধতি</label>
        <div class="seg mt-8"><button class="on">বাংলা (৳১২,৫০০)</button><button>ইংরেজি (৳12,500)</button></div>
        <div class="hlp">রসিদে সবসময় দুটোই থাকে — যাতে যে কেউ পড়তে পারে।</div></div>
      <div class="field mt-12"><label>টেক্সট সাইজ 🔵</label>
        <div class="seg mt-8"><button>ছোট</button><button class="on">সাধারণ</button><button>বড়</button></div>
        <div class="hlp">🔵 = Phase 3-এ আসবে</div></div>
    </div>

    ${secH('সম্মতি রেকর্ড', `${defChip('D-23')} সংস্করণসহ`)}
    <div class="card pad">
      ${CONSENTS.map(c => `<div class="hrow" style="padding:10px 0;border-bottom:1px dashed var(--line)">
        <span class="txi ${c.state === 'accepted' ? 'ok' : 'mut'}">${ic(c.state === 'accepted' ? 'checkc' : 'xc')}</span>
        <div class="grow" style="min-width:0"><div class="fs-sm b">${c.title} <span class="chip chip-neutral">v${bn(c.v)}</span></div>
          <div class="fs-xs mut">${c.at ? 'সম্মতি ' + dstr(c.at) : 'সম্মতি দেওয়া হয়নি'} · ${c.change}</div></div>
        ${c.required ? '<span class="chip chip-warn">বাধ্যতামূলক</span>' : `<button class="btn btn-ghost btn-sm">${c.state === 'accepted' ? 'প্রত্যাহার' : 'সম্মতি দিন'}</button>`}</div>`).join('')}
      <div class="alert alert-warn mt-12" style="padding:10px 12px;font-size:12.8px">${ic('warn','sm')}
        <div><b>প্রত্যাহারের ফলাফল</b>অবাধ্যতামূলক সম্মতি প্রত্যাহার করলে শুধু সেই সুবিধা বন্ধ হবে (যেমন গবেষণায় ডেটা শেয়ার)।
        বাধ্যতামূলক সম্মতি প্রত্যাহার করলে <b>অ্যাপ ব্যবহার করা যাবে না</b>, তবে অফিসে গিয়ে লেনদেন চলবে — আপনার টাকার হিসাব অক্ষত থাকবে।</div></div>
    </div>

    ${secH('অ্যাকাউন্ট')}
    <div class="card pad">
      ${row('history', 'লেনদেনের ইতিহাস ডাউনলোড', 'সম্পূর্ণ লেনদেন CSV/PDF হিসেবে', `<button class="btn btn-ghost btn-sm">${ic('download','sm')}</button>`)}
      ${row('freeze', 'অ্যাকাউন্ট সাময়িক লক', 'ফোন হারালে — একটি ক্লিকে সব লেনদেন বন্ধ', `<button class="btn btn-danger btn-sm">লক করুন</button>`)}
      ${row('logout', 'লগআউট', 'এই ডিভাইস থেকে', `<button class="btn btn-ghost btn-sm">লগআউট</button>`)}
    </div>

    <div class="t-c mt-16 mb-16"><div class="fs-xs mut">অ্যাপ ভার্সন ${P.appVersion} · ${ORG.name}</div>${staleNote()}</div>
  </div></div>
  ${bottomNav('more')}`;
}
/* ============================================================
   PHASE 2 · ADMIN (A-02, A-12, A-14)
   ============================================================ */

/* ---------- A-02 · মাঠ সংগ্রহক ড্যাশবোর্ড (COLLECTOR · মোবাইল) ---------- */
/* collector bottom nav (A-02 shell) */
function fieldNav(active) {
  const items = [
    { k: 'today', l: 'আজকের রুট', i: 'route', go: '#a02' },
    { k: 'find', l: 'সদস্য খুঁজুন', i: 'search', go: '#a10' },
    { k: 'entry', l: 'জমা এন্ট্রি', i: 'plus', fab: true, go: '#a17' },
    { k: 'dues', l: 'বকেয়া', i: 'warn', go: '#a31' },
    { k: 'sync', l: 'দিনশেষ', i: 'cash', go: '#a28' }];
  return `<div class="bottomnav">${items.map(n => n.fab
    ? `<button class="bnv bnv-fab ${active === n.k ? 'on' : ''}" onclick="go('${n.go}')"><span class="fab">${ic(n.i)}</span><span>${n.l}</span></button>`
    : `<button class="bnv ${active === n.k ? 'on' : ''}" onclick="go('${n.go}')">${ic(n.i)}<span>${n.l}</span></button>`).join('')}</div>`;
}

/* ---------- A-02 · মাঠ সংগ্রহক ড্যাশবোর্ড (মোবাইল ভ্যারিয়েন্ট) ----------
   নিরীক্ষা (ক/গ, 🔴): এটি আগে ডেস্কটপ A-02 স্ক্রিনকে ফোন-ফ্রেমে বসানো ছিল —
   সদস্য-অ্যাপের mhead, ডেস্কটপের .kpis/.kpi কার্ড, নিজস্ব fieldNav (ডেস্কটপ লিংক) এবং
   কোনো হ্যামবার্গার/ড্রয়ার ছিল না → সংগ্রহক এখান থেকে বাকি ANAV সেকশনে যেতেই পারতেন না (D-35 ভঙ্গ)।
   এখন Admin App শেলে (amScr) রূপান্তর: .amhead + ড্রয়ার + Shell-A বটম নেভ + কেবাব অ্যাকশন শিট,
   মোবাইল KPI (.amgrid/.amkpi), প্রধান CTA স্টিকি .decbar-এ, সব লিংক মোবাইল পর্দায় (#am…)। */
function A02() {
  const r = ROUTES[0];
  const dues = ROUTE_DUE_MEMBERS.filter(d => d.route === r.id);
  const pct = Math.round(r.collected / r.target * 100);
  const tel = n => 'tel:' + telHref(n);   /* ধাপ D: +৮৮ সহ আন্তর্জাতিক ফরম্যাট (গ্লোবাল telHref) */
  const routeAccounts = ACCOUNTS.filter(a => (member(a.memberId) || {}).route === r.id).slice(0, 5);

  const body = `
        <div class="offline-bar">${ic('wifioff')} <b>অফলাইন</b> · ${bn(SYNC.queued)}টি এন্ট্রি কিউতে · সংযোগ পেলে স্বয়ংক্রিয় সিঙ্ক হবে
          <a class="link" onclick="go('#s08')">বিস্তারিত</a></div>

        <div class="card pad" style="background:linear-gradient(150deg,var(--green-800),var(--green-700));color:#fff;border:0">
          <div class="hrow"><span class="txi lime" style="background:rgba(255,255,.16);color:#fff">${ic('route')}</span>
            <div class="grow"><b style="font-size:16px;display:block">${r.name}</b>
            <div style="font-size:12.4px;color:#A8CFBF">${r.area} · ${r.day}</div></div>
            <span class="chip" style="background:rgba(255,255,.18);color:#fff;border-color:rgba(255,255,.3)">${bn(r.members)} সদস্য</span></div>
          <div class="hrow mt-12" style="align-items:flex-end">
            <div class="grow"><div style="font-size:12.4px;color:#A8CFBF">আজ সংগৃহীত</div>
              <div style="font-size:32px;font-weight:700;line-height:1.2;font-variant-numeric:tabular-nums">${tk(r.collected)}</div>
              <div style="font-size:12.4px;color:#A8CFBF">লক্ষ্য ${tk(r.target)} · ${tkEn(r.collected)}</div></div>
            <div class="t-c"><div style="font-size:26px;font-weight:700">${bn(pct)}%</div><div style="font-size:12px;color:#A8CFBF">অর্জন</div></div></div>
          <div class="prog mt-12" style="background:rgba(255,255,.22)"><i style="width:${pct}%;background:var(--lime)"></i></div>
          <div class="hrow mt-12" style="gap:8px">
            <div class="grow" style="background:rgba(255,255,.14);border-radius:12px;padding:9px 11px">
              <div style="font-size:11.5px;color:#A8CFBF">হাতে নগদ</div><b style="font-size:15px">${tk(r.cashInHand)}</b></div>
            <div class="grow" style="background:rgba(255,255,.14);border-radius:12px;padding:9px 11px">
              <div style="font-size:11.5px;color:#A8CFBF">বাকি সদস্য</div><b style="font-size:15px">${bn(r.members - 18)}/${bn(r.members)}</b></div></div>
        </div>

        <div class="amgrid mt-16">
          <div class="amkpi"><div class="l">${ic('cash','sm')} গতকাল জমা</div><div class="v">${tk(2620000)}</div>
            <div class="a">২৯ অক্টোবর · অফিসে জমা হয়েছে</div></div>
          <div class="amkpi warn"><div class="l">${ic('warn','sm')} মোট বকেয়া</div><div class="v">${tk(r.overdueAmt)}</div>
            <div class="a">${bn(r.dues)} জন সদস্য · রুট ${r.id}</div></div>
        </div>

        <div class="btn-row mt-12">
          <button class="btn btn-soft grow" onclick="go('#am04')">${ic('search','sm')} মোবাইল/QR দিয়ে খুঁজুন</button>
          <button class="btn btn-soft grow" onclick="go('#s08')">${ic('refresh','sm')} এখনই সিঙ্ক</button></div>

        ${secH('বকেয়া — আগে আদায়', `${bn(dues.length)} জন`)}
        <div class="stack-12">${dues.map(d => { const m = member(d.memberId) || {};
          return `<div class="card pad">
          <div class="hrow"><div class="avatar">${(m.photo || d.name[0])}</div>
            <div class="grow" style="min-width:0"><b class="fs-md sb">${d.name}</b>
            <div class="fs-xs mut">${d.mobile} · ${d.addr}</div></div>
            <div class="t-c"><div class="amt amt-h2 amt-neg">${tk(d.due)}</div><div class="fs-xs mut">${bn(d.age)} দিন</div></div></div>
          <div class="hrow mt-8" style="gap:6px;flex-wrap:wrap">
            <span class="chip ${d.age > 90 ? 'chip-danger' : d.age > 30 ? 'chip-warn' : 'chip-info'}">${d.age > 90 ? '৯০+ দিন · নিষ্ক্রিয় হতে পারে' : d.age > 30 ? '৩০+ দিন বকেয়া' : 'সাম্প্রতিক বকেয়া'}</span>
            <span class="chip chip-neutral">সর্বশেষ জমা ${d.last}</span></div>
          <div class="btn-row mt-12">
            <button class="btn btn-soft grow" onclick="go('#am06')">${ic('cash','sm')} সংগ্রহ করুন</button>
            <a class="btn btn-ghost" href="${tel(d.mobile)}" aria-label="${d.name}-কে কল করুন">${ic('phone','sm')} কল</a>
            <button class="btn btn-ghost" aria-label="প্রোফাইল দেখুন" onclick="go('#am05')">${ic('user','sm')}</button></div>
        </div>`; }).join('')}</div>

        ${secH('আজকের রুট তালিকা', 'ক্রম অনুযায়ী')}
        <div class="card pad">
          <div class="rows">${routeAccounts.map(a => {
            const m = member(a.memberId), sc = scheme(a.schemeId);
            const done = a.paidInstallments > 0;
            return `<div class="row" onclick="go('#am06')"><span class="txi ${done ? 'ok' : 'mut'}">${ic(done ? 'checkc' : 'clock')}</span>
              <div class="row-tx"><b>${m.name}</b><i>${sc.typeBn} · ${tk(sc.installment)} · ${m.village}</i></div>
              <span class="chip ${done ? 'chip-ok' : 'chip-neutral'}">${done ? 'আদায় হয়েছে' : 'বাকি'}</span>${ic('chev','sm')}</div>`; }).join('')}
          </div>
          <button class="btn btn-ghost btn-block mt-12" onclick="go('#am04')">সব ${bn(r.members)} জন সদস্য দেখুন</button>
        </div>

        ${secH('দিনশেষ')}
        <div class="card pad">
          <div class="alert alert-warn" style="padding:10px 12px;font-size:12.8px">${ic('warn','sm')}
            <div><b>দিন সমাপ্তি বাকি</b> — হাতের ${tk(r.cashInHand)} অফিসে জমা দিয়ে ঘোষণা করতে হবে।</div></div>
          <div class="kv mt-12"><i>গুনে পাওয়া নগদ</i><b>${tk(r.cashInHand)}</b></div>
          <div class="kv"><i>সিস্টেম অনুযায়ী</i><b>${tk(r.collected)}</b></div>
          <div class="kv"><i>পার্থক্য</i><b class="amt-pos">৳০ ✓</b></div>
          <button class="btn btn-soft btn-block mt-12" onclick="go('#am15')">${ic('checkc','sm')} দিনশেষ ক্যাশ বুক খুলুন</button>
        </div>

        ${secH('সম্ভাব্য অবস্থা', 'এই পেজে')}
        <div class="stack-8">
          <div class="card pad"><div class="fs-sm b">রুট বরাদ্দ নেই</div>
            <div class="state state-sm" style="padding:14px 0 4px">${ic('route')}<h4>আজ আপনার কোনো রুট বরাদ্দ নেই</h4>
            <p>ম্যানেজারের সাথে যোগাযোগ করুন — ০১৭১১-••••২২৭। রুট বরাদ্দ হলে এখানে দেখা যাবে।</p></div></div>
          <div class="card pad"><div class="fs-sm b">দিন বন্ধ হয়ে গেলে</div>
            <div class="alert alert-danger" style="margin-top:8px">${ic('lock')}<div><b>আজকের এন্ট্রি বন্ধ</b> —
              ৩০ অক্টোবরের দিন সমাপ্তি সম্পন্ন হয়েছে। নতুন এন্ট্রি পরের দিনের জন্য খুলবে।</div></div></div>
          <div class="card pad"><div class="fs-sm b">সিঙ্ক সংঘর্ষ</div>
            <div class="alert alert-warn" style="margin-top:8px">${ic('warn')}<div><b>১টি দ্বৈত এন্ট্রি শনাক্ত</b> —
              একই সদস্য, একই পরিমাণ — দুটি ডিভাইস থেকে। সমাধানের তালিকায় দেখুন।</div></div></div>
        </div>

        <div class="t-c mt-16 mb-16">${staleNote()}</div>`;

  return amScr({ role: 'COLLECTOR', limit: 0, active: 'today', back: false,
    title: 'আজকের সংগ্রহ', sub: `${dstr(TODAY, true)} · ${r.name}`,
    right: `<button class="iconbtn plain" aria-label="অফলাইন অবস্থা" title="অফলাইন — কিউতে ${bn(SYNC.queued)}টি এন্ট্রি" onclick="go('#s08')">${ic('wifioff')}</button>`,
    moreActions: [
      { l: 'সব সদস্য দেখুন', i: 'users', go: '#am04' },
      { l: 'বকেয়া রেজিস্টার', i: 'warn', go: '#am12' },
      { l: 'সিঙ্ক ও অফলাইন কিউ', i: 'refresh', go: '#s08' }],
    decbar: `<div class="decbar"><div class="decbar-note">আজ সংগৃহীত <b>${tk(r.collected)}</b> · লক্ষ্য ${tk(r.target)} · <b>${bn(pct)}%</b> · হাতে নগদ ${tk(r.cashInHand)}</div>
      <div class="decbar-r"><button class="btn btn-ghost grow" onclick="go('#am04')">${ic('search','sm')} খুঁজুন</button>
      <button class="btn btn-primary grow" onclick="go('#am06')">${ic('plus','sm')} দ্রুত জমা রেকর্ড</button></div></div>`,
    body: body });
}


/* ---------- A-12 · সদস্য অবস্থা পরিবর্তন ---------- */
function A12() {
  const m = member('m7'), a = ACCOUNTS.filter(x => x.memberId === m.id)[0];
  const hist = STATUS_HIST.filter(h => h.memberId === m.id);
  const opt = (k) => {
    const c = STATUS_CONSEQ[k], st = MEM_STATUS[k];
    return `<div class="radio-card ${k === 'suspended' ? 'rc-on' : ''}">
      <div class="rc-h"><span class="rc-dot"></span><span class="chip ${st.c}">${ic(st.i,'sm')}${st.t}</span>
        <span class="mut fs-xs" style="margin-left:auto">${k === 'suspended' ? 'নির্বাচিত' : ''}</span></div>
      <div class="rc-b">
        ${c.blocks.length ? `<div class="hrow" style="gap:6px;flex-wrap:wrap;margin-bottom:6px"><span class="mut fs-xs">বন্ধ হবে:</span>
          ${c.blocks.map(x => `<span class="chip chip-danger">${ic('xc','sm')}${x}</span>`).join('')}</div>` : ''}
        <div class="hrow" style="gap:6px;flex-wrap:wrap"><span class="mut fs-xs">চলবে:</span>
          ${c.keeps.map(x => `<span class="chip chip-ok">${ic('check','sm')}${x}</span>`).join('')}</div>
        <div class="note mt-8">${c.note}</div></div></div>`;
  };
  return admScreen('a12', 'A-12', 'সদস্য অবস্থা পরিবর্তন',
    'MANAGER · ORG_ADMIN (C/U) · APPROVER (A) · AUDITOR (R)',
    'অবস্থা বদলানোর আগেই <b>পরিণতি দেখানো হয়</b> — কী বন্ধ হবে, কী চলবে, কয়টি আবেদন আটকাবে। কারণ ও কার্যকর তারিখ বাধ্যতামূলক, যাতে পরে বিতর্ক না হয়।',
    `${T('should','SHOULD 🟡')}${T('','পরিণতি প্রিভিউ')}${T('','কারণ বাধ্যতামূলক')}${T('','ইতিহাস সংরক্ষিত')}${T('def','ডিফল্ট · D-07 dormant')}${T('def','ডিফল্ট · D-20 ফ্রিজ')}`,
    'status',
    `${adminTop('সদস্য অবস্থা পরিবর্তন', '<a onclick="go(\'#a07\')">সদস্য</a> / <a onclick="go(\'#a10\')">' + m.name + '</a> / অবস্থা পরিবর্তন',
      `<span class="chip chip-warn">${ic('clock','sm')} অনুমোদনসাপেক্ষ</span><button class="btn btn-ghost btn-sm">${ic('print','sm')} প্রিন্ট</button>`)}
    <div class="admin-content">
      <div class="grid2">
        <div class="stack-16">
          <div class="card"><div class="card-h"><b>সদস্য</b><span class="chip ${MEM_STATUS[m.status].c}">${ic(MEM_STATUS[m.status].i,'sm')}${MEM_STATUS[m.status].t}</span></div>
            <div class="card-b">
              <div class="hrow"><div class="avatar lg">${m.photo}</div>
                <div><div style="font-size:19px;font-weight:700">${m.name}</div>
                <div class="mut fs-sm">${m.no} · ${m.mobile} · যোগদান ${dstr(m.joined)}</div>
                <div class="mut fs-xs mt-4">${m.village}, ${m.union}, ${m.upazila} · রুট ${m.route}</div></div></div>
              <div class="kv mt-12"><i>সঞ্চয় অ্যাকাউন্ট</i><b>${a ? a.no + ' · ' + tk(a.posted) : '—'}</b></div>
              <div class="kv"><i>বকেয়া</i><b class="amt-neg">${tk(m.due)} · ১৯৮ দিন</b></div>
              <div class="kv"><i>চলমান উত্তোলন আবেদন</i><b>${bn(1)}টি (approved)</b></div>
              <div class="kv"><i>KYC</i><b>${m.kyc === 'verified' ? 'যাচাইকৃত' : 'বাকি'}</b></div>
              <div class="kv"><i>নমিনি</i><b>${m.nominee || 'নিবন্ধিত নেই ⚠️'}</b></div></div></div>

          <div class="card"><div class="card-h"><b>নতুন অবস্থা বেছে নিন</b><span class="mut fs-xs">প্রতিটির পরিণতি নিচে</span></div>
            <div class="card-b stack-12">${['active', 'dormant', 'suspended', 'exited'].map(opt).join('')}</div></div>
        </div>

        <div class="stack-16">
          <div class="card"><div class="card-h"><b>পরিবর্তনের বিবরণ</b><span class="chip chip-info">ফর্ম</span></div>
            <div class="card-b">
              <div class="alert alert-danger">${ic('warn')}<div><b>এই পরিবর্তনে যা আটকাবে</b>
                ১টি চলমান উত্তোলন আবেদন (${tk(500000)}) স্থগিত হবে · নতুন জমা বন্ধ থাকবে · সদস্যকে কারণসহ SMS যাবে।
                <a class="link" onclick="go('#a22')">উত্তোলন আবেদন দেখুন →</a></div></div>
              <div class="field mt-12"><label>কারণ (বাধ্যতামূলক)</label>
                <div class="chipset mt-8">${STATUS_REASONS.map((r, k) => `<span class="chip chip-btn ${k === 3 ? 'on' : ''}">${r}</span>`).join('')}</div>
                <textarea class="inp mt-8" rows="3">কমিটির সিদ্ধান্ত ২০২৬/১৪ অনুযায়ী — সমিতির ক্ষতিসাধনের অভিযোগ তদন্তাধীন। তদন্ত শেষ না হওয়া পর্যন্ত লেনদন স্থগিত।</textarea>
                <div class="hlp">কারণ ছাড়া জমা নেওয়া হবে না; এটি অডিট ট্রেইলে স্থায়ীভাবে থাকবে।</div></div>
              <div class="grid2 mt-12">
                <div class="field"><label>কার্যকর তারিখ</label><input class="inp" value="৩০ অক্টোবর ২০২৬ (আজ)"></div>
                <div class="field"><label>মেয়াদ (সাময়িক হলে)</label><input class="inp" value="তদন্ত শেষ না হওয়া পর্যন্ত"></div></div>
              <div class="field mt-12"><label>সদস্যকে জানানো হবে কি না</label>
                <div class="seg mt-8"><button class="on">হ্যাঁ — কারণসহ SMS + পুশ</button><button>না (কারণ লিখতে হবে)</button></div>
                <div class="hlp">ডিফল্ট: জানানো হয়। না জানালে কমিটির লিখিত কারণ লাগবে।</div></div>
              <div class="field mt-12"><label>প্রমাণ সংযুক্তি</label>
                <div class="hrow" style="gap:8px;flex-wrap:wrap"><span class="chip chip-ok">${ic('doc','sm')} কমিটির সিদ্ধান্ত ২০২৬/১৪.pdf</span>
                  <button class="btn btn-ghost btn-sm">${ic('plus','sm')} যোগ করুন</button></div></div>
            </div>
            <div class="card-f"><div class="hrow">
              <span class="mut fs-xs grow">maker ≠ checker — আপনি নিজেই অনুমোদন করতে পারবেন না (BR-04)</span>
              <button class="btn btn-ghost btn-sm">খসড়া সংরক্ষণ</button>
              <button class="btn btn-primary btn-sm">${ic('send','sm')} অনুমোদনের জন্য জমা</button></div></div></div>

          <div class="card"><div class="card-h"><b>অবস্থা পরিবর্তনের ইতিহাস</b><span class="chip chip-neutral">${bn(hist.length + 2)} এন্ট্রি</span></div>
            <div class="card-b"><table class="tbl">
              <thead><tr><th>তারিখ</th><th>পরিবর্তন</th><th>কারণ</th><th>করেছেন</th><th>অনুমোদন</th><th>SMS</th></tr></thead>
              <tbody>
                <tr><td class="nowrap">৩০ অক্টোবর ২০২৬</td><td><span class="chip chip-warn">প্রস্তাবিত</span></td>
                  <td>তদন্ত চলছে</td><td>আপনি</td><td>অপেক্ষমাণ</td><td>—</td></tr>
                ${hist.map(h => `<tr><td class="nowrap">${dstr(h.at)}</td>
                  <td><span class="chip ${MEM_STATUS[h.from].c}">${MEM_STATUS[h.from].t}</span> → <span class="chip ${MEM_STATUS[h.to].c}">${MEM_STATUS[h.to].t}</span></td>
                  <td class="fs-xs">${h.reason}</td><td>${h.by}</td><td>${h.approved}</td>
                  <td>${h.notified ? '<span class="chip chip-ok">পাঠানো</span>' : '<span class="chip chip-neutral">না</span>'}</td></tr>`).join('')}
              </tbody></table>
              <div class="note mt-8">পুরনো অবস্থায় ফেরানো যায় — ইতিহাস কখনো মুছে ফেলা হয় না (soft-delete, D-30)।</div></div></div>

          <div class="card"><div class="card-h"><b>⚠️ যেসব পরিবর্তন থেকে ফেরা কঠিন</b></div>
            <div class="card-b"><div class="alert alert-warn">${ic('warn')}<div><b>Exited / Deceased</b>
              এই অবস্থায় গেলে সব লেনদেন বন্ধ হয় এবং নতুন করে চালু করতে নতুন সদস্যপদের প্রক্রিয়া লাগে। রেকর্ড আর্কাইভে থাকবে, মুছবে না।</div></div>
              <div class="alert alert-info mt-12">${ic('info')}<div><b>Frozen বনাম Suspended</b>
              ফ্রিজে <b>জমা দেওয়া যাবে, উত্তোলন যাবে না</b> ${defChip('D-20')}; স্থগিত করলে দুটোই বন্ধ। সদস্যের টাকা আনার পথ রাখতে চাইলে Frozen বেছে নিন।</div></div></div></div>
        </div>
      </div>
    </div>`,
    `<span class="lbl">API</span><span class="val">POST /members/{id}/status-changes</span>
     <span class="lbl" style="margin-left:12px">আগে</span><span class="val">A-10, A-07, A-31</span>
     <span class="lbl" style="margin-left:12px">পরে</span><span class="val">A-10, A-22</span>`);
}

/* ---------- A-14 · নমিনি ও মৃত্যু দাবি ব্যবস্থাপনা ---------- */
function A14() {
  const open = DEATH_CLAIMS.filter(c => c.status !== 'settled'), done = DEATH_CLAIMS.filter(c => c.status === 'settled');
  const proofChip = (k) => { const map = { ok: ['chip-ok', 'সংযুক্ত ✓'], missing: ['chip-danger', 'বাকি'], na: ['chip-neutral', 'প্রযোজ্য নয়'], blur: ['chip-warn', 'অস্পষ্ট'] };
    return `<span class="chip ${map[k][0]}">${map[k][1]}</span>`; };
  const card = (c) => { const st = DC_STATUS[c.status];
    return `<div class="card">
      <div class="card-h"><div><b>${c.member}</b><div class="mut fs-xs">${c.accNo} · দাবি ${dstr(c.at)}</div></div>
        <span class="chip ${st.c}">${ic(st.i,'sm')}${st.t}</span></div>
      <div class="card-b">
        ${c.dispute ? `<div class="alert alert-neutral">${ic('warn')}<div><b>${bn(c.claimants)} জন দাবিদার — বিরোধ</b>
          নমিনি নিবন্ধিত নেই। কমিটির সিদ্ধান্ত ও ইউনিয়ন পরিষদ/আদালতের সনদ ছাড়া নিষ্পত্তি হবে না ${defChip('D-14')}।
          শান্ত ভাষায় যোগাযোগ করুন — লাল চিহ্ন নয়।</div></div>` : ''}
        <div class="hrow mt-12"><div class="grow"><div class="mut fs-xs">নমিনি</div><div class="b">${c.nominee}</div>
          ${c.nomineeNid ? `<div class="mut fs-xs">NID ${c.nomineeNid}</div>` : ''}</div>
          <div class="grow"><div class="mut fs-xs">অংশ</div><div class="b">${bn(c.share)}%</div></div>
          <div class="t-c"><div class="mut fs-xs">দাবিকৃত / ব্যালেন্স</div><div class="amt amt-sm">${tk(c.claimed)}</div>
          <div class="mut fs-xs">${tk(c.balance)}</div></div></div>
        <div class="hrow mt-12" style="gap:6px;flex-wrap:wrap">
          <span class="mut fs-xs">প্রমাণ:</span>
          <span class="chip chip-neutral">মৃত্যু সনদ ${proofChip(c.proofs.death)}</span>
          <span class="chip chip-neutral">নমিনির NID ${proofChip(c.proofs.nomineeNid)}</span>
          <span class="chip chip-neutral">সাক্ষী ${proofChip(c.proofs.witness)}</span>
          <span class="chip chip-neutral">হলফনামা ${proofChip(c.proofs.affidavit)}</span></div>
        <div class="kv mt-12"><i>আইনি নোটিশ</i><b>${c.notice}</b></div>
        <div class="kv"><i>কেস নোট</i><b class="fs-xs" style="font-weight:500">${c.note}</b></div>
        ${c.voucher ? `<div class="kv"><i>নিষ্পত্তি ভাউচার</i><b>${c.voucher} · ${dstr(c.settledAt)}</b></div>` : ''}
      </div>
      <div class="card-f"><div class="hrow">
        <button class="btn btn-ghost btn-sm" onclick="go('#a10')">${ic('user','sm')} সদস্য প্রোফাইল</button>
        ${c.status === 'settled' ? `<button class="btn btn-soft btn-sm" onclick="go('#a26')">${ic('doc','sm')} সনদ ও লেজার</button>` :
          `<button class="btn btn-ghost btn-sm">${ic('doc','sm')} প্রমাণ যাচাই</button>
           <button class="btn btn-ghost btn-sm">${ic('scale','sm')} নিষ্পত্তি হিসাব</button>
           <button class="btn btn-primary btn-sm" onclick="go('#a24')">${ic('cash','sm')} পেমেন্ট নির্দেশ</button>`}</div></div></div>`; };
  return admScreen('a14', 'A-14', 'নমিনি ও মৃত্যু দাবি ব্যবস্থাপনা',
    'MANAGER · ORG_ADMIN · APPROVER (A) · AUDITOR (R)',
    'মৃত্যু দাবি নিষ্পত্তি — <b>আইনসম্মত ও সহানুভূতিশীল</b>। এই পেজে লাল/সতর্ক রঙ নয়, শান্ত নিরপেক্ষ রঙ ও সহানুভূতিপূর্ণ ভাষা ব্যবহার করা হয়েছে (ডিজাইন নোট)।',
    `${T('should','SHOULD 🟡')}${T('','সহানুভূতিপূর্ণ টোন')}${T('','প্রমাণ চেকলিস্ট')}${T('','বিরোধ নিষ্পত্তি')}${T('def','ডিফল্ট · D-14 একাধিক দাবিদার')}`,
    'claim',
    `${adminTop('নমিনি ও মৃত্যু দাবি', '<a onclick="go(\'#a01\')">ড্যাশবোর্ড</a> / মৃত্যু দাবি',
      `<span class="chip chip-warn">${bn(open.length)}টি নিষ্পত্তি বাকি</span><button class="btn btn-primary btn-sm">${ic('plus','sm')} নতুন দাবি দাখিল</button>`)}
    <div class="admin-content">
      <div class="kpis">
        <div class="kpi warn"><div class="kpi-l">${ic('clock','sm')} প্রমাণ বাকি</div><div class="kpi-v">${bn(open.filter(c => c.status === 'proof_pending').length)}</div><div class="kpi-a">কী বাকি তার তালিকা দেখানো হয়</div></div>
        <div class="kpi purple"><div class="kpi-l">${ic('warn','sm')} বিরোধ</div><div class="kpi-v">${bn(open.filter(c => c.dispute).length)}</div><div class="kpi-a">একাধিক দাবিদার · কমিটির সিদ্ধান্ত দরকার</div></div>
        <div class="kpi"><div class="kpi-l">${ic('checkc','sm')} এই বছর নিষ্পত্তি</div><div class="kpi-v">${bn(done.length)}</div><div class="kpi-a">মোট ${tk(done.reduce((s, c) => s + c.claimed, 0))}</div></div>
        <div class="kpi danger"><div class="kpi-l">${ic('heart','sm')} নমিনি ছাড়া সদস্য</div><div class="kpi-v">${bn(38)}</div><div class="kpi-a">ঝুঁকি — রিমাইন্ডার পাঠান (A-33)</div></div>
      </div>

      <div class="tabs mt-20"><button class="on">নিষ্পত্তি বাকি (${bn(open.length)})</button><button>সম্পন্ন (${bn(done.length)})</button>
        <button>নমিনি যাচাই (${bn(NOMINEES.filter(n => n.status === 'pending').length)})</button><button>সব</button></div>

      <div class="grid2 mt-16">${open.map(card).join('')}</div>

      <div class="card mt-20"><div class="card-h"><b>নিষ্পত্তির ধাপ (প্রতিটি দাবিতে একই)</b><span class="chip chip-info">প্রক্রিয়া</span></div>
        <div class="card-b"><div class="tl">
          <div class="tl-i done"><b>১ · দাবি দাখিল ও মৃত্যু সনদ যাচাই</b><i>সনদের নম্বর অনলাইনে যাচাই করা হয় · কে: হিসাবরক্ষক</i></div>
          <div class="tl-i done"><b>২ · নমিনি পরিচয় নিশ্চিতকরণ</b><i>NID মিলিয়ে দেখা + দুই সাক্ষীর স্বাক্ষর + হলফনামা</i></div>
          <div class="tl-i cur"><b>৩ · আইনি নোটিশ প্রকাশ</b><i>দৈনিক পত্রিকায় নোটিশ — অন্য দাবিদার থাকলে ১৪ দিনে আপত্তি</i></div>
          <div class="tl-i"><b>৪ · নিষ্পত্তি পরিমাণ হিসাব</b><i>সব অ্যাকাউন্টের সম্মিলিত ব্যালেন্স − বকেয়া − চার্জ (সুদ নয়) · গণ-নিষ্পত্তি</i></div>
          <div class="tl-i"><b>৫ · অনুমোদন (maker ≠ checker)</b><i>সীমা অনুযায়ী MANAGER/APPROVER · ${tk(20000000)}-এর বেশি হলে ORG_ADMIN</i></div>
          <div class="tl-i"><b>৬ · পেমেন্ট ও সনদ</b><i>A-24 → ভাউচার · সদস্যের অবস্থা Deceased · অ্যাকাউন্ট Closed · রেকর্ড আর্কাইভ (D-30)</i></div>
        </div></div></div>

      <div class="card mt-20"><div class="card-h"><b>সম্পন্ন দাবি</b></div>
        <div class="card-b"><table class="tbl">
          <thead><tr><th>সদস্য</th><th>নমিনি</th><th class="num">প্রদান</th><th>ভাউচার</th><th>নিষ্পত্তি</th><th>সনদ</th></tr></thead>
          <tbody>${done.map(c => `<tr><td><b>${c.member}</b><div class="fs-xs mut">${c.accNo}</div></td><td>${c.nominee}</td>
            <td class="num">${tk(c.claimed)}</td><td class="num">${c.voucher}</td><td class="nowrap">${dstr(c.settledAt)}</td>
            <td><button class="btn btn-ghost btn-sm">${ic('doc','sm')} দেখুন</button></td></tr>`).join('')}</tbody></table></div></div>
    </div>`,
    `<span class="lbl">API</span><span class="val">GET/POST /death-claims · /{id}/approve · /{id}/settle</span>
     <span class="lbl" style="margin-left:12px">পরে</span><span class="val">A-15, A-24, A-26</span>
     <span class="lbl" style="margin-left:12px">বিশেষ</span><span class="val">সহানুভূতিপূর্ণ ভাষা · লাল রঙ এড়ানো হয়েছে</span>`);
}
