            <td><span class="chip ${IMPORT_STATUS[x.status].c}">${ic(IMPORT_STATUS[x.status].i,'sm')}${IMPORT_STATUS[x.status].t}</span>
              ${x.err ? `<div class="fs-xs" style="color:var(--danger-ink);max-width:34ch">${x.err}</div>` : ''}</td>
