              <div class="field"><label>ভুলের ধরন</label>
                <div class="chipset mt-8">${['পরিমাণ ভুল', 'ভুল সদস্য/অ্যাকাউন্ট', 'তারিখ ভুল', 'মাধ্যম ভুল', 'ডুপ্লিকেট এন্ট্রি'].map((x, k) =>
                  `<span class="chip chip-btn ${k === 0 ? 'on' : ''}">${x}</span>`).join('')}</div></div>
