/* ISO timestamp -> "30 অক্টো · 08:42" (A-37/A-38 only) */
function dtm(x) {
  if (!x) return '—';
  const d = new Date(x);
  if (isNaN(d.getTime())) return '—';
  const hh = String(d.getHours()).padStart(2, '0'), mm = String(d.getMinutes()).padStart(2, '0');
  return dstr(x) + ' · ' + bn(hh + ':' + mm);
}
function dtshort(x) {
  if (!x) return '—';
  const d = new Date(x);
  if (isNaN(d.getTime())) return '—';
  const hh = String(d.getHours()).padStart(2, '0'), mm = String(d.getMinutes()).padStart(2, '0');
  return dshort(x) + '<br><span class="mut">' + bn(hh + ':' + mm) + '</span>';
}

