            <div class="field"><label>ভূমিকা</label><select class="inp"><option>সব ভূমিকা</option>${PERM_ROLES.map(r => `<option>${r}</option>`).join('')}<option>COLLECTOR</option><option>অজ্ঞাত</option></select></div>
