  const expOf = g => jgParts(g.id).filter(p => p.status === 'active' || p.status === 'behind')
    .reduce((s, p) => s + (g.crule === 'fixed' ? g.monthly : Math.round((p.pledged || 0) / jgTotalMonths(g))), 0);
  const gotOf = g => jgContribs(g.id).filter(c => c.at.slice(0, 7) === month).reduce((s, c) => s + c.amount, 0);
  const exp = goals.reduce((s, g) => s + expOf(g), 0), got = goals.reduce((s, g) => s + gotOf(g), 0);
  const ar = jgAllArrears();
